function CatHouseComponent:InitialDojo(data)
    self._catHouseHomeDojo = CatHouseHomeDojo.New()
    self._catHouseHomeDojo:Fill(data)
    self:RelevancePlayerPrivilegeCards(data)
    self:InitData()
    self:StartCDTimerModule()
    self:InitMergeSkillMap()
    self:InitAdultCatGenes()
    self:RegEvents()
end
--- 关联 privilegeCards 到 PlayerComponent
function CatHouseComponent:RelevancePlayerPrivilegeCards(data)
    ---@type PlayerComponent
    local playerComponent =  GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    playerComponent:InitPrivilegeCards(data.privilegeCards)
    self._catHouseHomeDojo.privilegeCards = playerComponent:GetPrivilegeCards()
end

---InitCDData
---初始化数据
function CatHouseComponent:InitData()

    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    --- 修正特权卡数据
    local privilegeCards = {}
    for i, v in pairs(checkTable(catHouseHomeDojo.privilegeCards)) do
        v.remainSeconds   = checkNumber(v.remainSeconds)
        v.privilegeCardId = checkNumber(v.privilegeCardId)
        privilegeCards[v.privilegeCardId] = v
    end
    catHouseHomeDojo.privilegeCards = privilegeCards


    local catId2CatData = {}
    --- {[catId] = {[key: CatStatus 猫状态] = [value:number 剩余时间]}}
    local catList       = catHouseHomeDojo.catList
    for i, catData in ipairs(catList) do
        local playerCatId = catData.id
        catId2CatData[checkNumber(playerCatId)] = catData

        self:FixCatData(catData)
        self:AddCDData(playerCatId, catData.status)
    end
    self._catId2CatData = catId2CatData

    --------------------------
    --- 处理培育红点
    self:UpdateDeliveryRedPoint()
    self:UpdateRallySignupRedPoint()

    if CatHouseExploreMgr then
        CatHouseExploreMgr:InitServiceData()
    end
end

---UpdateDeliveryRedPoint
---更新培育红点
function CatHouseComponent:UpdateDeliveryRedPoint()
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    local deliveryList = catHouseHomeDojo.deliveryList
    local catHouseDelivery = MaxNumberFlag
    for i, v in ipairs(deliveryList) do
        local status = checkNumber(v.status)
        if status == ConstantsCatHouse.CatCultivationType.Hatching then
            catHouseDelivery = math.min(catHouseDelivery, checkNumber(v.remainTime))
        end
    end
    catHouseDelivery = catHouseDelivery == MaxNumberFlag and -1 or catHouseDelivery
    GameUtils.UpdateServerRedPointData({catHouseDelivery = catHouseDelivery})
end

---UpdateFriendAskRegPoint
---更新猫屋好友孵化请求
---@param catHouseFriendAsk number 0 同意 -1
function CatHouseComponent:UpdateFriendAskRegPoint(catHouseFriendAsk)
    GameUtils.UpdateServerRedPointData({catHouseFriendAsk = catHouseFriendAsk})
end

---UpdateRallySignupRedPoint
---更新猫屋集会登记
function CatHouseComponent:UpdateRallySignupRedPoint()
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    local rallySignupList  = catHouseHomeDojo.rallySignupList
    local catHouseRallySignup = MaxNumberFlag
    for i, v in ipairs(rallySignupList) do
        if checkNumber(v.asked) == 1 then
            catHouseRallySignup = 0
            break
        else
            local playerCatId = checkNumber(v.playerCatId)
            if playerCatId > 0 then
                catHouseRallySignup = math.min(checkNumber(v.remainTime), catHouseRallySignup)
            end
        end
    end
    catHouseRallySignup = catHouseRallySignup == MaxNumberFlag and -1 or catHouseRallySignup
    GameUtils.UpdateServerRedPointData({catHouseRallySignup = catHouseRallySignup })
end

function CatHouseComponent:RegEvents()
    if self.EventConf then return end
    self.EventConf = {
        [Constants.EventNames.CatHouseFriendReplayHatchEventName] = Bind(self, self.OnEventFriendReplayHatch),
        [Constants.EventNames.CatHouseFriendReqHatchEventName] = Bind(self, self.OnEventFriendReqHatch),
        [Constants.EventNames.CatHouseRallyReplayHatchEventName] = Bind(self, self.OnEventRallyReplayHatch),
    }
    for eventName, handler in pairs(self.EventConf) do
        Events.AddListener(eventName, handler)
    end
end
function CatHouseComponent:UnRegEvents()
    if self.EventConf == nil then
        return
    end
    for eventName, handler in pairs(self.EventConf) do
        Events.RemoveListener(eventName, handler)
    end
    self.EventConf = nil
end

