---GetUnlockGenesByKind
---获取指定类型的解锁基因
---@param kind number 基因类型
function CatHouseComponent:GetUnlockGenesByKind(kind)
    kind = checkInt(kind)
    local unlockGenes = self:GetUnlockGenes()
    ---@type BaseSetting
    local setting = CfUtils.GetCf(AutoIds.IdSetting1902, CatHouseCatDataVo)
    local t = {}
    local dict = {}
    for geneId, v in pairs(unlockGenes) do
        ---@type CatHouseCatDataVo
        local vo = setting:Get(geneId)
        if vo.kind == kind then
            table.insert(t, vo)
            dict[tostring(vo.id)] = vo
        end
    end
    return t, dict
end

---基因数据分为两类，1是部件基因以外的,2是部件基因
---@param genes table 基因list
function CatHouseComponent:Process2ClassifyGenes(genes, ifInFancyShow)
    if isNull(ifInFancyShow) then
        ifInFancyShow = false
    end
    local geneMap = {
        [1] = {--部件基因以外的

        },
        [2] = {--部件基因

        },
    }

    for k, v in pairs(genes) do
        ---@type CatHouseCatDataVo
        local geneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", v.geneId)
        if ifInFancyShow then
            if geneData.infancyShow == 1 then
                if geneData.kind == ConstantsCatHouse.ScreenCatDataType.Part then
                    --部件基因
                    table.insert(geneMap[2], v)
                else
                    table.insert(geneMap[1], v)
                end
            end
        else
            if geneData.kind == ConstantsCatHouse.ScreenCatDataType.Part then
                --部件基因
                table.insert(geneMap[2], v)
            else
                table.insert(geneMap[1], v)
            end
        end

    end
    return geneMap
end

