---@param data table 训练编队数据 teamComponent:GetBufferTeam()
---@param catData table 猫数据，用来判断技能是否生效
---@return table @ 附加的属性值 Map 属性id = 属性值
function CatHouseComponent:GetSubjoinAttr(data, catData)
    local attrData = {} -- id == num <==> 属性id = 属性值范围的List
    local activeSkill = {}
    local finalAddition = {}

    local catAttrVo = CfUtils.GetWholeVo(AutoIds.IdSetting1901, "CatHouseCatAttributeVo")
    for k, v in pairs(catAttrVo) do
        --赋初值
        attrData[checkString(v.id)] = {0,0}
        activeSkill[v.id] = {
            low = {
                [1] = 0,--固定值
                [2] = 0--百分比
            },
            up = {
                [1] = 0,--固定值
                [2] = 0--百分比
            },
        }
        finalAddition[v.id] = {
            [1] = 0,--固定值
            [2] = 0--百分比
        }

    end
    if isNull(data) then
        return attrData
    end

    local isEmpty = true
    for i, v in pairs(data) do
        if table.count(v) ~= 0 then
            isEmpty = false
            break
        end
    end
    if isEmpty then
        return attrData
    else
        --初始加成
        for p, q in pairs(attrData) do
            local catAttrData = CfUtils.GetCfVo(AutoIds.IdSetting1901, "CatHouseCatAttributeVo", p)
            attrData[p] = self:AddAttrNumArea(attrData[p], catAttrData.trailRange, 0, 0, false)
        end
        for k, cardData in pairs(data) do--每个成员
            if table.count(cardData) > 0 then
                local vo =  CfUtils.GetCfVo(AutoIds.IdSetting1915, "CatCardTrainSkillVo", cardData.refId)
                local cardSkillData = vo.skillGroup
                --技能额外加成
                for i, b in pairs(cardSkillData) do--该成员的技能
                    local cardDojo = cardComponent:GetCardById(cardComponent:GetIdByCardId(cardData.refId))
                    if checkNumber(cardDojo.star) >= checkNumber(b.starLv) then--大于等于才会解锁
                        local skillVo = CfUtils.GetCfVo(AutoIds.IdSetting1917, "CatTrainSkillVo", b.additionId)
                        local catAttrData = CfUtils.GetCfVo(AutoIds.IdSetting1901, "CatHouseCatAttributeVo", skillVo.attributeId)
                        print("skill----->>"..table.dump(skillVo))
                        if checkNumber(skillVo.catId) == 0 or checkNumber(skillVo.catId) == checkNumber(catData.catId) then--全部生效 or 对指定猫种生效
                        -- EFFECT_LOWER_LIMIT_FIXED = 101;--_target_id_属性的培养下限值增加_target_num_（固定值）
                        -- EFFECT_LOWER_LIMIT_PERCENTAGE = 102;--_target_id_属性的培养下限值增加_target_num_（百分比）
                        -- -EFFECT_UPPER_LIMIT_FIXED = 201;--_target_id_属性的培养上限值增加_target_num_（固定值）
                        -- EFFECT_UPPER_LIMIT_PERCENTAGE = 202;--_target_id_属性的培养上限值增加_target_num_（百分比）
                        -- EFFECT_ADDITION_FIXED = 301;--仅对_target_id_猫生效，使提升的_target_id_属性额外增加_target_num_（固定值）
                        -- EFFECT_ADDITION_PERCENTAGE = 302;--仅对_target_id_猫生效，使提升的_target_id_属性额外增加_target_num_（百分比）
                        -- EFFECT_LIMIT_FIXED = 401;--仅对携带_target_id_数据的_target_id_猫生效，_target_id_属性的培养上限与下限值均增加_target_num_（固定值）
                        -- EFFECT_LIMIT_PERCENTAGE = 402;--仅对携带_target_id_数据的_target_id_猫生效，_target_id_属性的培养上限与下限值均增加_target_num_（百分比）
                            local effectId = checkNumber(skillVo.effectId)
                            if effectId == 101 then
                                activeSkill[skillVo.attributeId].low[1] = activeSkill[skillVo.attributeId].low[1] + b.additionNum
                            elseif effectId == 102 then
                                activeSkill[skillVo.attributeId].low[2] = activeSkill[skillVo.attributeId].low[2] + b.additionNum
                            elseif effectId == 201 then
                                activeSkill[skillVo.attributeId].up[1] = activeSkill[skillVo.attributeId].up[1] + b.additionNum
                            elseif effectId == 202 then
                                activeSkill[skillVo.attributeId].up[2] = activeSkill[skillVo.attributeId].up[2] + b.additionNum
                            elseif effectId == 301 then
                                finalAddition[skillVo.attributeId][1] = finalAddition[skillVo.attributeId][1] + b.additionNum
                            elseif effectId == 302 then
                                finalAddition[skillVo.attributeId][2] = finalAddition[skillVo.attributeId][2] + b.additionNum
                            elseif effectId == 401 then
                                activeSkill[skillVo.attributeId].low[1] = activeSkill[skillVo.attributeId].low[1] + b.additionNum
                                activeSkill[skillVo.attributeId].up[1] = activeSkill[skillVo.attributeId].up[1] + b.additionNum
                            elseif effectId == 402 then
                                activeSkill[skillVo.attributeId].low[2] = activeSkill[skillVo.attributeId].low[2] + b.additionNum
                                activeSkill[skillVo.attributeId].up[2] = activeSkill[skillVo.attributeId].up[2] + b.additionNum
                            end
                        end
                    end
                end
            end
        end
        print("activeSkill--->>"..table.dump(activeSkill, nil, 3))
        print("finalAddition--->>"..table.dump(finalAddition))
        for attrId, range in pairs(attrData) do
            attrData[attrId][1] = ((attrData[attrId][1] + activeSkill[checkNumber(attrId)].low[1]) * (1 + activeSkill[checkNumber(attrId)].low[2]) + finalAddition[checkNumber(attrId)][1]) * (1 + finalAddition[checkNumber(attrId)][2])
            attrData[attrId][2] = ((attrData[attrId][2] + activeSkill[checkNumber(attrId)].up[1]) * (1 + activeSkill[checkNumber(attrId)].up[2]) + finalAddition[checkNumber(attrId)][1]) * (1 + finalAddition[checkNumber(attrId)][2])
        end
    end
    return attrData
end

