function CatHouseComponent:GetTrainCardsTeamByAttrId(attrId, catData)
    attrId = checkNumber(attrId)
    local t = CfUtils.GetWholeVo(AutoIds.IdSetting1915, "CatCardTrainSkillVo")
    local cards = {}
    for k, v in pairs(t) do
        --if table.count(cards) >= 4 then
        --    return cards
        --end
        if attrId == checkNumber(v.attributeId) then
            local data
            if cardComponent:IsHasCard(v.id) then
                --data = cardComponent:GetCardById(cardComponent:GetIdByCardId(v.id))
            --else
                data = CardConfMgr:GetInstance():GetCardByRefId(v.id)
                data["catIdSort"] = (table.keyof(v.catId, checkString(catData.catId)) ~= nil) and 9 or 1 --用于做排序，猫种相同前置
                table.insert(cards, data)
            end
        end
    end
    ---属性>猫种>稀有度>星级
    table.sort(cards, function(a, b)
        local aData = cardComponent:GetCardById(cardComponent:GetIdByCardId(a.roleId))
        local bData = cardComponent:GetCardById(cardComponent:GetIdByCardId(b.roleId))
        if a.catIdSort ~= b.catIdSort then
            return a.catIdSort > b.catIdSort
        elseif a.rare ~= b.rare then
            return a.rare < b.rare
        elseif aData.star ~= bData.star then
            return aData.star > bData.star
        end
        return false
    end)



    if table.count(cards) < 4 then
        for i = table.count(cards) + 1, 4 do
            cards[i] = {}
        end
    end

    if table.count(cards) > 4 then
        for i = table.count(cards), 5, -1 do
            table.remove(cards, i)
        end
    end
    return cards
end


