        for i, v in ipairs(catHouseHomeDojo.exploreList) do
            v.remainTime = UpdateTime(v.remainTime, elapsed)

        end

        ---
        if self._friendReplyList then
            for i, v in ipairs(self._friendReplyList) do
                v.remainTime = UpdateTime(v.remainTime, elapsed)

            end
        end

        -- self:StartCatHpTimes()
        Events.Broadcast(CatHouseTimeChange)

    end, CountDownTime, false, true)
end

