function CatHouseComponent:GetCatCDData()
    return self._catCDData
end
function CatHouseComponent:RemoveCDDataByKey(key)
    self._catCDData[tostring(key)] = nil
end
---UpdateCDData
---@param id number 猫的唯一id
---@param remainTime number 剩余时间
---@param status number ConstantsCatHouse.CatStatus
function CatHouseComponent:UpdateCDData(id, status, remainTime)
    local cdData = self:GetCDDataById(id)
    if cdData then
        cdData[checkNumber(status)] = remainTime
        self:GetCatDataById(id).status = cdData
    elseif remainTime then
        ---倒计时缓存没有并且有剩余时间 则新创建个倒计时数据
        cdData = { [checkNumber(status)] = remainTime }
        self:AddCDData(id, cdData)
        self:GetCatDataById(id).status = cdData
    end
end
---UpdateCDData
---@param id number 猫的唯一id
---@param status table<number, number> <CatStatus, remainTime>
function CatHouseComponent:AddCDData(id, status)
    if next(status) == nil then
        return
    end
    self._catCDData[tostring(id)] = status
end

function CatHouseComponent:GetCDDataById(id)
    return self._catCDData[tostring(id)]
end

function CatHouseComponent:GetCatDataById(id)
    --for k, v in pairs(self._catHouseHomeDojo.catList) do
    --    if checkNumber(v.id) == id then
    --        return self._catHouseHomeDojo.catList[k]
    --    end
    --end
    return self._catId2CatData[checkNumber(id)]
end

function CatHouseComponent:SetCatDataById(id, data)
    id = checkNumber(id)
    for k, v in pairs(self._catHouseHomeDojo.catList) do
        if checkNumber(v.id) == id then
            local isNullData = data == nil
            if isNullData then
                if checkNumber(v.isShow) == 1 then
                    self._catHouseHomeDojo:FillFieldData("localCatShowNum", checkNumber(self._catHouseHomeDojo.localCatShowNum) - 1)
                end
                table.remove(self._catHouseHomeDojo.catList, k)
            else
                self._catHouseHomeDojo.catList[k] = data
            end
            self._catId2CatData[checkNumber(id)] = data
            break
        end
    end
    if not isNull(data) then
        self:FixCatData(data)
        self:AddCDData(id, data.status)

        self:AddAdultCatGenes(data)
    else
        self:RemoveCDDataByKey(id)
    end
end

---当前猫咪是否能被初始化（卖掉）
---@param id number 猫的唯一id
function CatHouseComponent:CanInitialCat(id)
    id = checkString(id)
    local canInit = false
    for k, v in pairs(self._catHouseHomeDojo.catList) do
        if checkString(v.id) ~= id then
            if id ~= checkString(self._catHouseHomeDojo.partyCatId) then
                canInit = true
                break
            end
        end
    end
    return canInit
end

function CatHouseComponent:AddCatData(data)
    ---1. 修正数据
    self:FixCatData(data)

    ---2. 添加到全局缓存中
    table.insert(self._catHouseHomeDojo.catList, data)
    self._catId2CatData[checkNumber(data.id)] = data
    self:AddCDData(data.id, data.status)

    self:AddAdultCatGenes(data)
end

function CatHouseComponent:FixCatData(data)
    data.catId = checkNumber(data.petId)
    local t = {}
    local status = checkTable(data.status)
    for state, seconds in pairs(status) do
        t[checkNumber(state)] = seconds
    end
    data.status = t
end

function CatHouseComponent:SetDeliveryData(deliveryId, deliveryData)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    for i, v in ipairs(catHouseHomeDojo.deliveryList) do
        if checkNumber(v.deliveryId) == deliveryId then
            catHouseHomeDojo.deliveryList[i] = deliveryData
        end
    end
end

function CatHouseComponent:AddDeliveryData(deliveryId, expirationTime)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    table.insert(catHouseHomeDojo.deliveryList, { deliveryId = deliveryId, status = 0, expirationTime = expirationTime or 0, remainTime = 0 })
end

function CatHouseComponent:ClearDeliveryDataById(deliveryId, isRemove)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    local deliveryList = catHouseHomeDojo.deliveryList
    for i, v in ipairs(deliveryList) do
        if checkNumber(v.deliveryId) == deliveryId then
            deliveryList[i] = (not isRemove) and { deliveryId = deliveryId, status = 0, expirationTime = 0, remainTime = 0 } or nil
            return deliveryList[i]
        end
    end
end

