--初始化所有猫的成年基因
function CatHouseComponent:InitAdultCatGenes()
    self._adultCatGenes = {}
    self._adultCatTypes = {}

    local t = self:GetCatHouseHomeDojo()
    if t then
        t = t.catList
        if t then
            print(table.dump(t))
            for k, v in pairs(t) do
                if checkNumber(v.age) == ConstantsCatHouse.BornType.Adult then
                    local genesT = checkTable(t.genes)
                    for _k, _v in pairs(genesT) do
                        self._adultCatGenes[checkString(_v)] = 1
                    end
                end

                self._adultCatTypes[checkString(v.petId)] = 1
            end
        end
    end
    print(table.dump(self._adultCatTypes))
    print(table.dump(self._adultCatGenes))
end 

function CatHouseComponent:AddAdultCatGenes(data)
    if not data then
        return
    end
    --只要成年猫的
    if checkNumber(data.age) ~= ConstantsCatHouse.BornType.Adult then
        return
    end
    local genesT = checkTable(data.genes)
    for _k, _v in pairs(genesT) do
        if checkNumber(self._adultCatGenes[checkString(_v.geneId)]) == 0 then
            self:CheckAdultCatGene(1002, _v.geneId)
            self._adultCatGenes[checkString(_v.geneId)] = 1
        end 
    end

    if checkNumber(self._adultCatTypes[checkString(data.petId)]) == 0 then
        self._adultCatTypes[checkString(data.petId)] = 1
        self:CheckAdultCatGene(1001, data.petId)
    end

    --self:CheckAdultCatGene(1002, 3102)
    --self:CheckAdultCatGene(1002, 3103)
end

function CatHouseComponent:CheckAdultCatGene(cdtType, id)
    cdtType = checkNumber(cdtType)
    id = checkNumber(id)
    if id <= 0 then
        return
    end
    --先判断是否是加成基因
    if checkInt(cdtType) == Constants.CommonUnlockType.CatHouseCatGene then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", id)
        if vo then
            --有加成数据
            if vo.variationKindList and #vo.variationKindList > 0 then
                table.insert(self._allPopData, {text1 = localize("通过基因"), text2 = vo.name, genId = id })
                --Events.Broadcast("CAT_GET_POPUP_FINISH", )
            end

            local targetMergeSkillId = self:GetMergeSkillByTypeOrGene(cdtType, id)
            if checkNumber(targetMergeSkillId) > 0 then
                --已经解锁
                if checkNumber(self._mergeSillMap[checkString(targetMergeSkillId)]) == 1 then

                else
                    self._mergeSillMap[checkString(targetMergeSkillId)] = 1
                    table.insert(self._allPopData, { text1 = localize("通过基因"), text2 = vo.name, skillId = targetMergeSkillId })
                end
            end
        end
    elseif checkInt(cdtType) == Constants.CommonUnlockType.CatHouseCatType then  --类型
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", id)
        
        if vo then
            local targetMergeSkillId = self:GetMergeSkillByTypeOrGene(cdtType, id)
            if checkNumber(targetMergeSkillId) > 0 then
                --已经解锁
                if checkNumber(self._mergeSillMap[checkString(targetMergeSkillId)]) == 1 then

                else
                    self._mergeSillMap[checkString(targetMergeSkillId)] = 1
                    table.insert(self._allPopData, { text1 = localize("通过猫种"), text2 = vo.name, skillId = targetMergeSkillId })
                end
            end
        end        
    end
end 

--初始化合卡技 map
function CatHouseComponent:InitMergeSkillMap()
    self._mergeSillMap = {}

    local t = CfUtils.GetCfTable(AutoIds.IdSetting569)
    if not t then
        return
    end

    local UnitSkillVo = import("Game.Setting.Vo.UnitSkillVo")
    for k, v in pairs(t) do
        local vo = UnitSkillVo.New()
        vo:FillVo(v)
        local isUnlock = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockId)
        self._mergeSillMap[checkString(vo.skillId)] = isUnlock and 1 or 0
    end
    print(table.dump(self._mergeSillMap))
end

--获取条件对应的合卡技
function CatHouseComponent:GetMergeSkillByTypeOrGene(cdtType, id)
    cdtType = checkNumber(cdtType)
    id = checkNumber(id)
    if id <= 0 then
        return
    end

    local targetMergeSkillId = 0
    local t = checkTable(self._mergeSillMap)
    for k, v in pairs(t) do
        --未解锁的进来判断
        if checkNumber(v) == 0 then
            local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(k)
            if vo then
                --找到满足参数条件的id
                if checkNumber(vo.unlockType) == cdtType and checkNumber(vo.unlockId) == id then
                    targetMergeSkillId = checkNumber(k)
                end
            end
        end
    end
    return targetMergeSkillId
end

---CheckMergeSkillByTypeOrGene
---判断合卡技 
---@param cdtType number 条件类型 1002,--猫屋猫基因 1001,--猫屋猫种
---@param id number id
function CatHouseComponent:CheckMergeSkillByTypeOrGene(cdtType, id)
    cdtType = checkNumber(cdtType)
    id = checkNumber(id)
    if id <= 0 then
        return
    end

    local targetMergeSkillId = 0
    local t = checkTable(self._mergeSillMap)
    for k, v in pairs(t) do
        --未解锁的进来判断
        if checkNumber(v) == 0 then
            local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(k)
            if vo then
                --找到满足参数条件的id
                if checkNumber(vo.unlockType) == cdtType and checkNumber(vo.unlockId) == id then
                    targetMergeSkillId = checkNumber(k)
                end
            end
        end
    end

    --没有新的合卡技解锁
    if targetMergeSkillId <= 0 then
        return
    end
    --刷新本地数据
    self._mergeSillMap[checkString(targetMergeSkillId)] = 1

    local text1, text2 = "", ""
    if checkInt(cdtType) == Constants.CommonUnlockType.CatHouseCatType then
        --猫种
        text1 = localize("通过猫种")
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", id)
        if vo then
            text2 = vo.name
        end
    elseif checkInt(cdtType) == Constants.CommonUnlockType.CatHouseCatGene then
        --基因
        text1 = localize("通过基因")
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", id)
        if vo then
            text2 = vo.name
        end
    end

    print(table.dump({ text1 = text1, text2 = text2, skillId = targetMergeSkillId }))
    table.insert(self._allPopData, { text1 = text1, text2 = text2, skillId = targetMergeSkillId })

    --Events.Broadcast("CAT_GET_POPUP_FINISH", )
end

function CatHouseComponent:GetPopData()
    if not self._allPopData or table.count(self._allPopData) <= 0 then
        return nil
    end
    local t = self._allPopData[#self._allPopData]
    table.remove(self._allPopData, #self._allPopData)
    return t
end

--第一次进来时获取打脸合卡技
function CatHouseComponent:GetMergeSkillWithBorn()
    if not self._mergeSillMap then
        return {}
    end

    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local catInfo = playerComponent.playerDojo.partyCatInfo
    if not catInfo then
        return {}
    end

    local targetMergeSkillId = 0
    for k, v in pairs(self._mergeSillMap) do
        local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(k)
        if vo then
            if checkNumber(vo.unlockType) == Constants.CommonUnlockType.CatHouseCatType then
                if checkNumber(vo.unlockId) == checkNumber(catInfo.catId) then
                    targetMergeSkillId = checkNumber(k)
                    break
                end
            elseif checkNumber(vo.unlockType) == Constants.CommonUnlockType.CatHouseCatGene then
                local genesT = checkTable(catInfo.genes)
                for k, v in pairs(genesT) do
                    if checkNumber(v) == checkNumber(vo.unlockId) then
                        targetMergeSkillId = checkNumber(k)
                        break
                    end
                end
            end
        end
    end

    --没有新的合卡技解锁
    if targetMergeSkillId <= 0 then
        return {}
    end

    local skillVo = QuestConfMgr:GetInstance():GetMergeSkillVo(targetMergeSkillId)
    if not skillVo then
        return {}
    end
    local text1, text2 = "", ""
    if checkInt(skillVo.unlockType) == Constants.CommonUnlockType.CatHouseCatType then
        --猫种
        text1 = localize("通过猫种")
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", skillVo.unlockId)
        if vo then
            text2 = vo.name
        end
    elseif checkInt(skillVo.unlockType) == Constants.CommonUnlockType.CatHouseCatGene then
        --基因
        text1 = localize("通过基因")
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", skillVo.unlockId)
        if vo then
            text2 = vo.name
        end
    end

    return { text1 = text1, text2 = text2, skillId = targetMergeSkillId }
end

function CatHouseComponent:GetPrivilegeCardById(id)
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    id = checkInt(id)
    local privilegeCard    = {}
    for i, v in pairs(catHouseHomeDojo.privilegeCards) do
        if id == v.privilegeCardId then
            privilegeCard = v
            break
        end
    end
    --catHouseHomeDojo.privilegeCards[id] or {}
    return privilegeCard
end

function CatHouseComponent:GetPrivilegeCardSecondsById(id)
    local privilegeCard = self:GetPrivilegeCardById(id)
    if privilegeCard.lastTime then
        local remainSeconds = privilegeCard.remainSeconds - (os.time() - privilegeCard.lastTime)
        if remainSeconds < 0 then
            return 0
        else
            return remainSeconds
        end
    end
    return privilegeCard.remainSeconds or 0
end

function CatHouseComponent:OnEventFriendReplayHatch(t)
    local result           = checkNumber(t.result)
    local playerCatId      = checkNumber(t.playerCatId)
    local childPlayerCatId = checkNumber(t.childPlayerCatId)
    local friendCatId      = checkNumber(t.friendCatId)
    local friendId         = checkNumber(t.friendId)

    local UpdateDeliveryList = function(status, remainTime, _childPlayerCatId)
        local deliveryList = self:GetCatHouseHomeDojo().deliveryList
        for i, deliveryData in ipairs(deliveryList) do
            ---处于好友确认中
            if checkNumber(deliveryData.status) == ConstantsCatHouse.CatCultivationType.FriendsConfirming then
                if friendId == checkNumber(deliveryData.friend.playerId) and
                        playerCatId == checkNumber(deliveryData.playerCatId) and
                        friendCatId == checkNumber(deliveryData.friendCat.id)
                then
                    deliveryData.status = status
                    deliveryData.remainTime = remainTime
                    deliveryData.childPlayerCatId = _childPlayerCatId
                end
            end
        end
    end

    --- 如果是同意
    if result == 1 then
        ---1. 给自己的猫咪设置上恢复时间
        local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchRecoverSeconds).num)
        self:UpdateCDData(playerCatId, CatStatus.Recovering, remainTime)

        ---2. 给自己的猫咪清理等待状态
        self:UpdateCDData(playerCatId, CatStatus.Waiting)

        ---3. 拉去猫数据
        GameUtils.Request(Interfaces.CatHouseCat, {playerCatId = childPlayerCatId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then return end
            local responseData = checkTable(response.data)
            local catData = responseData.cat
            self:AddCatData(catData)

            local seconds = self:GetCDDataById(catData.id)[CatStatus.Hatching]
            ---3 找到对应的孵化列表 更新数据
            UpdateDeliveryList(ConstantsCatHouse.CatCultivationType.Hatching, seconds, childPlayerCatId)
        end)

    elseif result == 2 then
        --- 好友拒绝后
        ---1 需要更新自己猫的等待状态
        self:UpdateCDData(playerCatId, CatStatus.Waiting, 0)
        ---2 将培育列表变成好友拒绝状态
        UpdateDeliveryList(ConstantsCatHouse.CatCultivationType.FriendsConfirmingFail, 0)

    end

    Events.Broadcast(ConstantsCatHouse.PacketsCatHouseFriendReplayHatch, t)
end

function CatHouseComponent:OnEventRallyReplayHatch(t)
    local rallyId     = checkNumber(t.rallyId)
    if rallyId == 0 then return end
    local playerCatId     = checkNumber(t.playerCatId)
    local rallySignupList = self:GetCatHouseHomeDojo().rallySignupList
    for i, v in pairs(rallySignupList) do
        if checkNumber(v.rallyId) == rallyId and checkNumber(v.playerCatId) == playerCatId then
            v.remainTime = 0
            v.asked      = 1
            ---@type CatHouseComponent
            local catData = self:GetCatDataById(playerCatId)
            catData.deliveryRemainTimes = checkNumber(catData.deliveryRemainTimes) - 1
            self:UpdateCDData(playerCatId, CatStatus.Signup)

            ---将配对的猫变为 恢复状态
            local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchRecoverSeconds).num)
            self:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Recovering, remainTime)
            break
        end
    end

    Events.Broadcast(ConstantsCatHouse.PacketsCatHouseRallyReplayHatch, t)
end


function CatHouseComponent:OnEventFriendReqHatch(t)
    Events.Broadcast(ConstantsCatHouse.PacketsCatHouseFriendReqHatch, t)
end


return CatHouseComponent